<?php require_once __DIR__.'/../../middleware/bootstrap.php';require_once __DIR__.'/../../config/database.php';$user=require_login();if($_SERVER['REQUEST_METHOD']==='GET')json_out(['user'=>$user]);$d=body();if(empty($d['name'])||!valid_email($d['email']??''))json_out(['message'=>'Name and valid email are required.'],422);$s=$pdo->prepare('SELECT id FROM users WHERE email=? AND id<>?');$s->execute([strtolower($d['email']),$user['id']]);if($s->fetch())json_out(['message'=>'That email is already used by another account.'],409);$s=$pdo->prepare('UPDATE users SET name=?,email=?,phone=? WHERE id=?');$s->execute([trim($d['name']),strtolower($d['email']),substr(trim($d['phone']??''),0,40),$user['id']]);$user['name']=trim($d['name']);$user['email']=strtolower($d['email']);$user['phone']=substr(trim($d['phone']??''),0,40);$_SESSION['user']=$user;json_out(['message'=>'Profile saved.','user'=>$user]);
